from dataclasses import dataclass
from simpa.utils.libraries.tissue_library import TissueLibrary

dataclass


class DatasetConfig:
    """Base configuration for datasets."""

    # where to save the generated data
    output_path: str = "SIMPA/data"

    # where to find the segmentation maps (hdf5 files generated by OA-US-Analysis pipeline)
    segmentation_map_path: str = "SIMPA/data/segmentation_maps"
    # name of the hdf5 dataset
    hdf5_dataset = ["POSTPROCESSING/MASK"]

    skin_id: int = 1
    epidermis_id: int = 11
    dermis_id: int = 12
    epidermis_px: int = 1
    wavelengths: list = [700, 850, 980]

    # whether to simulate partial volume effects in the segmentation volume
    # effects can also be included in the segmentation mask already
    pv_effect: bool = False


@dataclass
class FSTDatasetConfig(DatasetConfig):
    """Configuration for the FST dataset."""

    name: str = "FSTDataset"

    melanin_min_intensity: float = 0.75
    melanin_max_intensity: float = 4.0
    melanin_min_fraction: float = 0.01
    melanin_max_fraction: float = 0.30

    output_path: str = "SIMPA/data_fst"
    segmentation_map_path: str = "SIMPA/data_fst/segmentation_maps"
    skin_intensity_xlsx_path: str = "SIMPA/data_fst/skin_melanin_intensity.xlsx"


@dataclass
class PADDatasetConfig(DatasetConfig):
    """Configuration for the PAD dataset."""

    name: str = "PADDataset"

    melanin_min_intensity: float = 0.06
    melanin_max_intensity: float = 2.84
    melanin_min_fraction: float = 0.01
    melanin_max_fraction: float = 0.10

    output_path: str = "SIMPA/data_pad"
    segmentation_map_path: str = "SIMPA/data_pad/segmentation_maps"
    skin_intensity_xlsx_path: str = "SIMPA/data_pad/skin_melanin_intensity.xlsx"


@dataclass
class SIMDatasetConfig(DatasetConfig):
    """Configuration for the simulated dataset (full accoustic sim)."""

    name: str = "SIMDataset"

    output_path: str = "SIMPA/data_sim"
    segmentation_map_path: str = "SIMPA/data_sim/segmentation_maps"

    hdf5_dataset = ["POSTPROCESSING/MASK_HYBRID"]

    random_mel_range: tuple = (0.01, 0.15)


def segmentation_class_mapping(subject_data):
    """
    Mapping from segmentation class ids to tissue properties for the optical simulation.
    defaults: melanin_volume_fraction=0.014, muscle_oxy=0.6
    dermis: oxygenation=0.75, blood_volume_fraction=0.03
    vessels: oxygenation=0.8
    """
    ret_dict = dict()

    ret_dict[11] = TissueLibrary.epidermis(
        melanin_volume_fraction=subject_data.get("melanin_fraction", 0.014)
    )  # Skin - > epidermis
    ret_dict[12] = TissueLibrary.dermis(
        oxygenation=subject_data.get("skin_oxy", 0.75),
        blood_volume_fraction=subject_data.get("skin_bvf", 0.03),
    )  # Skin - > dermis
    ret_dict[2] = TissueLibrary.soft_tissue(oxygenation=0.1)  # Fascia1
    ret_dict[6] = TissueLibrary.soft_tissue(oxygenation=0.1)  # Fascia2
    # this gives a tissue with spectra between muscle and fat (close to fat)
    # since fascia is often treated as an intermediate between those layers
    # and there is no data in literature for fascia
    ret_dict[3] = TissueLibrary.muscle(
        oxygenation=subject_data.get("muscle_oxy", 0.6), blood_volume_fraction=0.2
    )  # Muscle (gastro)
    ret_dict[4] = TissueLibrary.muscle(
        oxygenation=subject_data.get("muscle_oxy", 0.6), blood_volume_fraction=0.2
    )  # Muscle (soleus)

    ret_dict[5] = TissueLibrary.mediprene()  # Membrane
    ret_dict[7] = TissueLibrary.heavy_water()  # Transducer
    ret_dict[8] = TissueLibrary.subcutaneous_fat()  # SAT
    ret_dict[9] = TissueLibrary.ultrasound_gel()  # gel
    ret_dict[0] = TissueLibrary.constant(0, 10, 1)  # background

    # vessles (in case they were added to the seg mask)
    ret_dict[13] = TissueLibrary.blood(
        oxygenation=subject_data.get("vessel_oxy", 0.8)
    )  # vessel in muscle
    ret_dict[14] = TissueLibrary.blood(
        oxygenation=subject_data.get("vessel_oxy", 0.8)
    )  # vessel in SAT

    return ret_dict
